with RECURSIVE UserBadgesCTE as (
    select u.Id as UserId,
           u.DisplayName,
           b.Name as BadgeName,
           b.Date as BadgeDate,
           b.Class as BadgeClass,
           ROW_NUMBER() OVER (PARTITION BY u.Id ORDER BY b.Class, b.Date desc) AS UserBadgeRank
      from Users u 
 LEFT OUTER JOIN Badges b on b.UserId = u.Id
  where u.Reputation > 1000
),
RecentQuestionsCTE as (
  select p.Id, p.OwnerUserId, p.CreationDate, p.Score, p.ViewCount, p.Score::float/coalesce(nullif(p.ViewCount,0),1) as ScoreViewRatio,
